function validate([nums, k, dist]) {
  const n = nums.length;
  if (n < 3 || n > 100000) return 'nums needs 3 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value is a whole number from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 3 || k > n) return 'k is a whole number from 3 to n.';
  if (!Number.isInteger(dist) || dist < k - 2 || dist > n - 2) return 'dist is a whole number from k - 2 to n - 2.';
  return null;
}

