function minimumCost(nums, k, dist) {
  const n = nums.length;
  const need = k - 1;
  // A Fenwick tree over the distinct values counts how many of each are in the window, and their sum.
  const sorted = [...new Set(nums.slice(1))].sort((a, b) => a - b);
  const rank = new Map(sorted.map((value, i) => [value, i + 1]));
  const size = sorted.length;
  const count = new Array(size + 1).fill(0);
  const total = new Array(size + 1).fill(0);

  function update(value, delta) {
    for (let i = rank.get(value); i <= size; i += i & -i) {
      count[i] += delta;
      total[i] += delta * value;
    }
  }

  // Sum of the `need` smallest values currently in the window.
  function smallestSum() {
    let step = 1;
    while (step * 2 <= size) step *= 2;
    let pos = 0;
    let taken = 0;
    let sum = 0;
    for (; step > 0; step = Math.floor(step / 2)) {
      if (pos + step <= size && taken + count[pos + step] < need) {
        pos += step;
        taken += count[pos];
        sum += total[pos];
      }
    }
    return sum + (need - taken) * sorted[pos];
  }

  for (let i = 1; i <= dist + 1; i++) update(nums[i], 1);
  let best = smallestSum();
  for (let i = dist + 2; i < n; i++) {
    update(nums[i], 1);
    update(nums[i - dist - 1], -1);
    best = Math.min(best, smallestSum());
  }
  return nums[0] + best;
}

