function minimumCost(nums, k, dist) {
  // Try every set of k - 1 starting indices after index 0.
  let best = Infinity;
  const starts = [];
  const choose = from => {
    if (starts.length === k - 1) {
      if (starts[starts.length - 1] - starts[0] <= dist) {
        best = Math.min(best, nums[0] + starts.reduce((s, i) => s + nums[i], 0));
      }
      return;
    }
    for (let i = from; i < nums.length; i++) {
      starts.push(i);
      choose(i + 1);
      starts.pop();
    }
  };
  choose(1);
  return best;
}

