function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(3, 10);
  const top = size === 'large' ? (rand() < 0.5 ? 1e9 : 50) : (rand() < 0.2 ? 1e9 : int(1, 9));
  const nums = Array.from({ length: n }, () => int(1, top));
  const k = size === 'large' && rand() < 0.7 ? int(3, Math.min(n, 60)) : int(3, n);
  const dist = rand() < 0.4 ? int(k - 2, Math.min(n - 2, k + 5)) : int(k - 2, n - 2);
  return [nums, k, dist];
}
